import * as THREE from './vendor/three.module.js';

const rows={idle:{row:0,frames:6,fps:5,label:'AU REPOS'},run:{row:1,frames:8,fps:10,label:'EN MOUVEMENT'},wave:{row:3,frames:4,fps:5,label:'BONJOUR'},jump:{row:4,frames:5,fps:7,label:'UN PEU D’ÉNERGIE'},failed:{row:5,frames:8,fps:6,label:'CONNEXION INTERROMPUE'},thinking:{row:6,frames:6,fps:5,label:'À VOTRE ÉCOUTE'},focus:{row:7,frames:6,fps:5,label:'CONCENTRATION'}};
export function initScene(container,{onTap,onState,onFallback}){
  let state='idle',stateStart=performance.now(),loop=false,night=false,disposed=false,paused=false,raf,frame=-1;
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
  const fallback=document.getElementById('fallback-pet');
  let renderer;
  try{renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,powerPreference:'low-power'});}catch{fallback.hidden=false;onFallback();return fallbackScene();}
  renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0x000000,0);renderer.outputColorSpace=THREE.SRGBColorSpace;container.append(renderer.domElement);
  const world=new THREE.Scene();
  const camera=new THREE.PerspectiveCamera(32,1,.1,80);let yaw=0,targetYaw=0,distance=8.6;
  const atlas=new THREE.TextureLoader().load('assets/2b-sprites.png',undefined,undefined,()=>{fallback.hidden=false;onFallback();});atlas.colorSpace=THREE.SRGBColorSpace;atlas.repeat.set(1/8,1/11);atlas.offset.set(0,10/11);atlas.magFilter=THREE.LinearFilter;atlas.minFilter=THREE.LinearFilter;atlas.generateMipmaps=false;
  const character=new THREE.Sprite(new THREE.SpriteMaterial({map:atlas,transparent:true,depthWrite:false}));character.scale.set(3.65,3.65*208/192,1);character.position.set(0,1.99,0);world.add(character);
  const ground=new THREE.Mesh(new THREE.CircleGeometry(3.05,100),new THREE.MeshBasicMaterial({color:0xc8cebb,transparent:true,opacity:.12,depthWrite:false}));ground.rotation.x=-Math.PI/2;ground.position.y=-.025;world.add(ground);
  const rings=[];
  for(const radius of [1.18,2.25,2.9]){const mesh=new THREE.Mesh(new THREE.RingGeometry(radius,radius+.008,120),new THREE.MeshBasicMaterial({color:0x9da58f,transparent:true,opacity:.34,side:THREE.DoubleSide,depthWrite:false}));mesh.rotation.x=-Math.PI/2;mesh.position.y=-.012;rings.push(mesh);world.add(mesh);}
  // A soft contact shadow is generated independently of the pet artwork.
  const shadowCanvas=document.createElement('canvas');shadowCanvas.width=128;shadowCanvas.height=128;const ctx=shadowCanvas.getContext('2d');const gradient=ctx.createRadialGradient(64,64,0,64,64,64);gradient.addColorStop(0,'rgba(40,50,35,0.24)');gradient.addColorStop(1,'rgba(40,50,35,0)');ctx.fillStyle=gradient;ctx.fillRect(0,0,128,128);const shadowTexture=new THREE.CanvasTexture(shadowCanvas);const shadow=new THREE.Mesh(new THREE.PlaneGeometry(2.1,1.2),new THREE.MeshBasicMaterial({map:shadowTexture,transparent:true,depthWrite:false}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.001;world.add(shadow);
  const particleGeo=new THREE.BufferGeometry();const particlePositions=new Float32Array(42*3);for(let i=0;i<42;i++){particlePositions[i*3]=(Math.random()-.5)*8;particlePositions[i*3+1]=Math.random()*4;particlePositions[i*3+2]=(Math.random()-.5)*5;}particleGeo.setAttribute('position',new THREE.BufferAttribute(particlePositions,3));const particles=new THREE.Points(particleGeo,new THREE.PointsMaterial({color:0x9ca58c,size:.017,transparent:true,opacity:.4,depthWrite:false}));world.add(particles);
  const pod=new THREE.Group();const podBody=new THREE.Mesh(new THREE.BoxGeometry(.2,.3,.15),new THREE.MeshBasicMaterial({color:0x646e58,wireframe:true,transparent:true,opacity:.6}));pod.add(podBody);const podEye=new THREE.Mesh(new THREE.SphereGeometry(.023,8,8),new THREE.MeshBasicMaterial({color:0x9fae85}));podEye.position.set(0,.025,.09);pod.add(podEye);pod.position.set(1.15,2.5,0);world.add(pod);
  function resize(){const {width,height}=container.getBoundingClientRect();if(width<1||height<1)return;renderer.setSize(width,height,false);camera.aspect=width/height;camera.updateProjectionMatrix();distance=camera.aspect<.9?10.2:8.6;}
  const observer=new ResizeObserver(resize);observer.observe(container);resize();
  let pointer=null;
  container.addEventListener('pointerdown',down);container.addEventListener('pointermove',move);container.addEventListener('pointerup',up);container.addEventListener('pointercancel',cancel);
  function down(e){if(e.button!==0)return;pointer={id:e.pointerId,startX:e.clientX,startY:e.clientY,x:e.clientX,moved:false};container.setPointerCapture(e.pointerId);}
  function move(e){if(!pointer||e.pointerId!==pointer.id)return;const dx=e.clientX-pointer.x;if(Math.hypot(e.clientX-pointer.startX,e.clientY-pointer.startY)>8)pointer.moved=true;if(pointer.moved)targetYaw=Math.max(-.9,Math.min(.9,targetYaw+dx*.006));pointer.x=e.clientX;}
  function up(e){if(!pointer||pointer.id!==e.pointerId)return;const click=!pointer.moved;pointer=null;if(click)onTap();}
  function cancel(){pointer=null;}
  function animate(now){if(disposed)return;raf=requestAnimationFrame(animate);if(paused)return;const time=now*.001;const row=rows[state];const elapsed=(now-stateStart)/1000;if(state!=='idle'&&!loop&&elapsed>=row.frames/row.fps*(state==='focus'?4:2)){state='idle';stateStart=now;frame=-1;onState(rows.idle.label);}const active=rows[state];const currentFrame=reduced?0:Math.floor((now-stateStart)/1000*active.fps)%active.frames;if(currentFrame!==frame){atlas.offset.set(currentFrame/8,(10-active.row)/11);frame=currentFrame;}yaw+=(targetYaw-yaw)*.06;camera.position.set(Math.sin(yaw)*distance,3.1,Math.cos(yaw)*distance);camera.lookAt(0,1.85,0);pod.position.y=2.5+(reduced?0:Math.sin(time*1.4)*.065);pod.rotation.y=reduced?0:Math.sin(time*.6)*.2;if(!reduced)particles.rotation.y=time*.013;renderer.render(world,camera);}
  function visibility(){paused=document.hidden;}document.addEventListener('visibilitychange',visibility);
  renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();paused=true;fallback.hidden=false;onFallback();});
  renderer.domElement.addEventListener('webglcontextrestored',()=>{paused=false;fallback.hidden=true;});
  raf=requestAnimationFrame(animate);
  return {play(next,repeat=false){if(!rows[next])return;state=next;stateStart=performance.now();loop=repeat;frame=-1;onState(rows[next].label);},reset(){targetYaw=0;},setNight(value){night=value;rings.forEach(r=>r.material.color.set(night?0x778c67:0x9da58f));ground.material.color.set(night?0x506349:0xc8cebb);particles.material.color.set(night?0xa1b98c:0x9ca58c);podBody.material.color.set(night?0xb4c69e:0x646e58);},destroy(){disposed=true;cancelAnimationFrame(raf);observer.disconnect();document.removeEventListener('visibilitychange',visibility);container.removeEventListener('pointerdown',down);container.removeEventListener('pointermove',move);container.removeEventListener('pointerup',up);container.removeEventListener('pointercancel',cancel);world.traverse(o=>{o.geometry?.dispose();if(o.material){for(const m of Array.isArray(o.material)?o.material:[o.material])m.dispose();}});atlas.dispose();shadowTexture.dispose();renderer.dispose();}};
  function fallbackScene(){let interval;function play(next,repeat=false){clearInterval(interval);const r=rows[next]||rows.idle;let i=0,cycles=0;onState(r.label);function update(){fallback.style.backgroundPosition=`${-192*i}px ${-208*r.row}px`;i++;if(i>=r.frames){i=0;cycles++;if(!repeat&&next!=='idle'&&cycles>=2)play('idle',true);}}update();interval=setInterval(update,1000/r.fps);}container.addEventListener('click',onTap);play('idle',true);return {play,reset(){},setNight(){},destroy(){clearInterval(interval);container.removeEventListener('click',onTap);}};}
}
